describe("delete a task", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  async function createdId(title: string): Promise<number> {
    const { task } = (await (await createTask(server, title)).json()) as { task: Task };
    return task.id;
  }

  it("DELETE /api/tasks/:id answers 204 and the task leaves the list, others stay", async () => {
    const doomed = await createdId("Doomed");
    const kept = await createdId("Kept");

    const response = await fetch(`${server.baseUrl}/api/tasks/${doomed}`, { method: "DELETE" });
    assert.equal(response.status, 204);
    assert.equal(await response.text(), "");

    const ids = (await listTasks(server)).map((t) => t.id);
    assert.ok(!ids.includes(doomed));
    assert.ok(ids.includes(kept));
  });

  it("deleting an unknown or already deleted id answers 404 not_found", async () => {
    const id = await createdId("Once");
    await fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });

    for (const target of [String(id), "999999", "abc"]) {
      const response = await fetch(`${server.baseUrl}/api/tasks/${target}`, { method: "DELETE" });
      assert.equal(response.status, 404, target);
      const body = (await response.json()) as { error: { code: string } };
      assert.equal(body.error.code, "not_found");
    }
  });

  it("a deleted task stays gone after kill -9 and a restart", async () => {
    const dbPath = newDbPath();
    let running = await startServer(dbPath);
    try {
      const { task } = (await (await createTask(running, "Gone")).json()) as { task: Task };
      const response = await fetch(`${running.baseUrl}/api/tasks/${task.id}`, { method: "DELETE" });
      assert.equal(response.status, 204);
      await running.stop();
      running = await startServer(dbPath);
      assert.deepEqual(await listTasks(running), []);
    } finally {
      await running.stop();
    }
  });

  it("the page asks for confirmation before it sends DELETE", async () => {
    const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    assert.match(script, /confirm\(/);
    assert.match(script, /method:\s*"DELETE"/);
    assert.ok(script.indexOf("confirm(") < script.indexOf('"DELETE"'));
  });
});
EOF
